 const transcribe=async()=>{const src=p.clips[0]?.src||p.videoSrc||p.overlays.find(o=>o.kind==='audio')?.src;if(!src)return setError('Importe um vídeo ou áudio antes.');setError('');setRenderJob('Iniciando Whisper local...');try{const r=await fetch('/api/transcribe',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({src,model,language:'Portuguese'})}),d=await r.json();if(!r.ok)throw Error(d.error);await jobPoll(d.id,'transcribe',src);notify('Legendas geradas, revisadas e selecionadas. Elementos existentes foram preservados.');}catch(e){setError(String(e));}finally{setRenderJob('');}};
