 const suggestStyles=async()=>{if(!transcriptCues.length)return setError('Gere ou importe legendas antes de pedir estilos à IA.');setError('');setRenderJob('Gemini sugerindo estilos para a faixa de legendas...');try{const r=await fetch('/api/ai-style',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({cues:transcriptCues,model:agModel})}),data=await r.json();if(!r.ok)throw Error(data.error);if(!Array.isArray(data.presets)||data.presets.length!==transcriptCues.length)throw Error('A IA não retornou uma sequência válida');const styles=new Map(transcriptCues.map((c,i)=>[c.id,data.presets[i]]));rec();setP(current=>({...current,cues:current.cues.map(c=>isTranscript(c)&&PRESETS.includes(styles.get(c.id))?{...c,preset:styles.get(c.id)}:c)}));notify('Estilos aplicados somente às legendas geradas.');}catch(e){setError(String(e));}finally{setRenderJob('');}};
