 const addKeyframe=()=>{if(!selected||selected.kind==='word')return;const item=cue||overlay||clip;if(!item)return;const x=(item as any).x??50,y=(item as any).y??50,scale=(item as any).scale??(item as VideoClip).zoom??1,rotation=(item as any).rotation??0,opacity=(item as any).opacity??1;const k:Keyframe={time:cursor,x,y,scale,rotate:rotation,opacity};const keyframes=[...((item as any).keyframes||[]).filter((v:Keyframe)=>Math.abs(v.time-cursor)>1/fps),k].sort((a,b)=>a.time-b.time);if(cue)editCue(cue.id,{keyframes});if(overlay)editLayer(overlay.id,{keyframes});if(clip)editClip(clip.id,{keyframes});notify('Keyframe adicionado no tempo '+seconds(cursor));};
 const applyPosition=(x:number,y:number,undo=false)=>{if(!selected)return;const patch={x:clamp(x,0,100),y:clamp(y,0,100)};const moveCaptionGroup=selected.kind==='cue'&&selectedCueIds.length>1&&selectedCueIds.includes(selected.id);if(moveCaptionGroup){const origins=captionPreviewOrigins.current??(captionPreviewOrigins.current=p.cues.filter(item=>selectedCueIds.includes(item.id)).map(clone));const anchor=origins.find(item=>item.id===selected.id);const dx=patch.x-(anchor?.x??50),dy=patch.y-(anchor?.y??70);if(undo)rec();setP(current=>({...current,cues:current.cues.map(item=>{const origin=origins.find(v=>v.id===item.id);return origin?{...item,x:clamp((origin.x??50)+dx,0,100),y:clamp((origin.y??70)+dy,0,100)}:item;})}));return;}if(keyframeMode&&selected.kind!=='word'){
   const item=cue||overlay||clip;if(!item)return;const prev=(item.keyframes||[]).filter(k=>Math.abs(k.time-cursor)>1/fps);const key:Keyframe={time:cursor,...patch};if(cue)editCue(cue.id,{keyframes:[...prev,key].sort((a,b)=>a.time-b.time)},undo);if(overlay)editLayer(overlay.id,{keyframes:[...prev,key].sort((a,b)=>a.time-b.time)},undo);if(clip)editClip(clip.id,{keyframes:[...prev,key].sort((a,b)=>a.time-b.time)},undo);
  }else {if(cue)editCue(cue.id,patch,undo);if(overlay)editLayer(overlay.id,patch,undo);if(clip)editClip(clip.id,patch,undo);}};
