   if(snapEnabled){const threshold=9/zoom;const marks=[0,duration,...p.clips.filter(v=>v.id!==d.id).flatMap(v=>[v.start,v.end]),...p.cues.filter(v=>v.id!==d.id).flatMap(v=>[v.start,v.end]),...p.overlays.filter(v=>v.id!==d.id).flatMap(v=>[v.start,v.end])];const snap=(v:number)=>marks.reduce((best,m)=>Math.abs(m-v)<Math.abs(best-v)?m:best,v);if(d.mode==='move'){const target=snap(start);if(Math.abs(target-start)<=threshold){end+=target-start;start=target;}}else if(d.mode==='start'){const target=snap(start);if(Math.abs(target-start)<=threshold)start=target;}else{const target=snap(end);if(Math.abs(target-end)<=threshold)end=target;}}
