 const faceReframe=async()=>{const c=clip||p.clips[0];if(!c)return setError('Selecione um trecho de vídeo');const Detector=(window as any).FaceDetector;if(!Detector)return setError('Detecção de rosto indisponível neste navegador. Use keyframes manuais ou habilite FaceDetector no Chrome compatível.');setRenderJob('Analisando rostos no vídeo...');try{const vid=document.createElement('video');vid.crossOrigin='anonymous';vid.muted=true;vid.src=c.src;await new Promise<void>((ok,no)=>{vid.onloadedmetadata=()=>ok();vid.onerror=()=>no(Error('Vídeo indisponível'));});const detector=new Detector({fastMode:true,maxDetectedFaces:1});const canvas=document.createElement('canvas');canvas.width=480;canvas.height=270;const context=canvas.getContext('2d')!;const k:Keyframe[]=[];for(let t=c.start;t<c.end;t+=1){vid.currentTime=c.sourceStart+(t-c.start)*c.speed;await new Promise<void>(resolve=>{vid.onseeked=()=>resolve();});context.drawImage(vid,0,0,480,270);const faces=await detector.detect(canvas);if(faces.length){const bb=faces[0].boundingBox;k.push({time:t,x:clamp((bb.x+bb.width/2)/480*100,10,90),y:clamp((bb.y+bb.height/2)/270*100,10,90),scale:1.15});}}if(!k.length)throw Error('Nenhum rosto detectado');editClip(c.id,{keyframes:k});notify(`${k.length} keyframes de rosto adicionados (revise o enquadramento).`);}catch(e){setError(String(e));}finally{setRenderJob('');}};
 const analyzeAudio=async(f?:File)=>{if(!f)return;try{const src=await upload(f);const AudioCtx=(window as any).AudioContext||(window as any).webkitAudioContext;const ctx=new AudioCtx();const audio=await ctx.decodeAudioData((await f.arrayBuffer()).slice(0));const channel=audio.getChannelData(0),windowSize=Math.round(audio.sampleRate*.12),energy:number[]=[];for(let i=0;i<channel.length;i+=windowSize){let sum=0;for(let j=i;j<Math.min(i+windowSize,channel.length);j++)sum+=channel[j]*channel[j];energy.push(Math.sqrt(sum/windowSize));}const avg=energy.reduce((a,b)=>a+b,0)/(energy.length||1),peaks:number[]=[];for(let i=1;i<energy.length-1;i++)if(energy[i]>avg*1.7&&energy[i]>energy[i-1]&&energy[i]>=energy[i+1]&&(!peaks.length||i*.12-peaks[peaks.length-1]>.35))peaks.push(i*.12);const beats=peaks.slice(0,150).map(t=>({id:uid(),kind:'effect',type:'flash',name:'Beat flash',start:t,end:t+.17,track:4,x:50,y:50,scale:1,rotation:0,opacity:.13,color:'#ffffff'} as Overlay));change({overlays:[...p.overlays,{id:uid(),kind:'audio',name:f.name,src,start:0,end:audio.duration,track:0,x:50,y:50,scale:1,rotation:0,opacity:1,volume:1},...beats]});await ctx.close();notify(`Áudio e ${beats.length} pulsos de batida adicionados. Ajuste pela timeline.`);}catch(e){setError('Não foi possível analisar este áudio: '+String(e));}};
  useEffect(()=>{const h=(e:KeyboardEvent)=>{const t=e.target as HTMLElement;if(t?.matches('input,textarea,select,[contenteditable]'))return;if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='a'){e.preventDefault();setSelectedCueIds(transcriptCues.map(c=>c.id));if(transcriptCues[0])select({kind:'cue',id:transcriptCues[0].id});}else if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();undo();}else if((e.ctrlKey||e.metaKey)&&e.key==='y'){e.preventDefault();redo();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate();}else if(e.code==='Space'){e.preventDefault();togglePlay();}else if(e.key==='Delete'||e.key==='Backspace')deleteSelection();};window.addEventListener('keydown',h);return()=>window.removeEventListener('keydown',h);});
