 const trackRows=useMemo(()=>[{name:'🎞 VÍDEO',kind:'clip',items:p.clips.map(c=>({id:c.id,start:c.start,end:c.end,label:'Corte '+c.src.split('/').pop()?.slice(0,7)}))},{name:'💬 LEGENDAS GERADAS',kind:'cue',items:cueTracks(p.cues).captions.map(c=>({id:c.id,start:c.start,end:c.end,label:c.text.replace(/[\[\]]/g,'')}))},{name:'T TEXTOS MANUAIS / ESTILOS',kind:'cue',items:cueTracks(p.cues).texts.map(c=>({id:c.id,start:c.start,end:c.end,label:c.text.replace(/[\[\]]/g,'')}))},{name:'🔤 PALAVRAS DA LEGENDA',kind:'word',items:wordExpanded&&cue?normalizeWords(cue).map(w=>({id:w.id,start:w.start,end:w.end,label:w.text})):[]},{name:'🎬 B-ROLL',kind:'overlay',items:p.overlays.filter(o=>o.kind==='video'||o.mediaRole==='broll').map(o=>({id:o.id,start:o.start,end:o.end,label:o.name}))},{name:'🧩 ELEMENTOS LIVRES',kind:'overlay',items:p.overlays.filter(o=>o.mediaRole!=='broll'&&(o.kind==='shape'||o.kind==='image'||o.kind==='text')).map(o=>({id:o.id,start:o.start,end:o.end,label:o.name}))},{name:'✨ EFEITOS',kind:'overlay',items:p.overlays.filter(o=>o.kind==='effect').map(o=>({id:o.id,start:o.start,end:o.end,label:o.name}))},{name:'🔊 ÁUDIO',kind:'overlay',items:p.overlays.filter(o=>o.kind==='audio').map(o=>({id:o.id,start:o.start,end:o.end,label:o.name}))}], [p,wordExpanded,cue]);

